(window.SITE_LANG_DATA = window.SITE_LANG_DATA || {})["haw"] = {"ui":{"skip":"E lele i ka ʻike","back":"← E hoʻi i AI-gile","lang.button":"ʻŌlelo: {name}","lang.dialog":"E koho i kahi ʻōlelo","lang.search":"E ʻimi i nā ʻōlelo","lang.none":"ʻAʻohe ʻōlelo kūpono","lang.notYet":"ʻAʻole i unuhi ʻia ka {name}","theme.aria":"E hoʻololi i ke ʻano: ʻālohilohi, ʻeleʻele a i ʻole ʻeleʻele maoli","theme.toLight":"E hoʻololi i ke ʻano ʻālohilohi","theme.toDark":"E hoʻololi i ke ʻano ʻeleʻele","theme.toBlack":"E hoʻololi i ke ʻano ʻeleʻele maoli (ʻeleʻele piha, maikaʻi no nā pale OLED)","words.underline":"E kaha lalo i kēia mau hua ʻōlelo ma ka ʻaoʻao","words.underlineHelp":"E kau i ka ʻiole ma luna o kekahi hua ʻōlelo kiko, a i ʻole e paʻi iā ia, e ʻike ai i kona manaʻo.","index.title":"AI-gile: kāu pūʻulu hoʻomohala AI, ma hoʻokahi papa","index.description":"He papa kanban ʻo AI-gile no nā pūʻulu hoʻopaʻa code AI. Ke hana nei lākou i kou hiamoe ʻana; loaʻa iā ʻoe kekahi puʻu pōkole o nā mea e hoʻoholo ai, e hoʻāʻo ai a e ʻae ai.","hero.logoAlt":"Hōʻailona papa AI-gile","hero.h1.html":"Kāu pūʻulu hoʻomohala AI, ma hoʻokahi&nbsp;papa.","hero.alpha":"🐣 Pre-alpha pani ʻia","hero.alphaTitle":"Ma ka hoʻomaka a ʻaʻole i pau: mahalo no ka hoʻāʻo ʻana!","hero.lede":"Hana lākou i kou hiamoe ʻana. Ala ʻoe i kekahi puʻu pōkole: kekahi mau nīnau, kekahi mau mea e hoʻāʻo ai, hoʻokahi a ʻelua paha daimana poni. E kaomi, e ʻae, a e hoʻi i kāu kope.","dl.windows":"ʻApp Windows","dl.browser":"E holo ma kāu polokalamu kele","dl.messenger":"📱 Messenger no kāu kelepona","dl.soon":"E hiki mai ana","dl.notify":"🔔 E haʻi mai iaʻu ke wehe ʻia","dl.notifySmall":"Alpha a i ʻole beta","hero.secondary":"Agile, akā ʻaʻole pono i ka pūʻulu ke kope kū o ka hālāwai. (Hālāwai nō naʻe lākou.)","pitch.h2":"AI-gile i nā huaʻōlelo he nui a he liʻiliʻi e like me kāu makemake","pitch.lede":"E koho i ka lōʻihi, mai ka huaʻōlelo hoʻokahi a i 144. He wehewehe ponoʻī kēlā me kēia lōʻihi, i kākau ʻia no ia nui. E huki i ka ʻōwili a i ʻole e hoʻohana i nā pihi pua.","pitch.rangeLabel":"Ka lōʻihi ma nā huaʻōlelo","pitch.dice":"🎲 kekahi mana ʻē aʻe","pitch.words.one":"{n} huaʻōlelo","pitch.words.other":"{n} huaʻōlelo","pitch.letters.one":"{n} leka","pitch.letters.other":"{n} leka","pitch.chars.one":"{n} hōʻailona","pitch.chars.other":"{n} hōʻailona","count.line.html.one":"{n} kāleka ma ka papa i kēia manawa","count.line.html.other":"{n} kāleka ma ka papa i kēia manawa","people.humans.html.one":"👥 {n} kanaka","people.humans.html.other":"👥 {n} kānaka","people.agents.html.one":"🤖 {n} ʻelele","people.agents.html.other":"🤖 {n} ʻelele","people.working.html.one":"⚡ {n} e hana nei i kēia manawa","people.working.html.other":"⚡ {n} e hana nei i kēia manawa","features.aria":"Ka mea āna e hana ai","f.pile.h":"Hoʻokahi puʻu no ʻoe","f.pile.html":"Mālama ʻo <b>No ʻoe</b> i nā mea a pau e kali nei iā ʻoe, ma nā papahana a pau: nā nīnau, nā mea e hoʻāʻo ai, nā hana hiki i ke kanaka wale nō. Ua ʻōlelo kāu laina i ka mea aʻe a me ka lōʻihi o ka manawa.","f.sleep.h":"Nā pūʻulu hana i kou hiamoe ʻana","f.sleep.p":"He alakaʻi a he pūʻulu mea hana AI kā kēlā me kēia papahana. E ʻōlelo ma kekahi kāleka a ala ka pūʻulu, hana i ka hana, a hoʻihoʻi me nā ʻanuʻu hiki i ke kanaka luhi ke hahai.","f.tester.h":"Nānā mua ka mea hoʻāʻo AI","f.tester.p":"Ma mua o ka hiki ʻana mai o kekahi mea iā ʻoe, hahai ka mea hoʻāʻo i nā ʻanuʻu ma kahi kope o ka ʻapp a hōʻike i kāna i ʻike ai, me ke kiʻi pale. E nānā wikiwiki i ka mea i pono a e ʻae me ke kaomi hoʻokahi.","f.proof.h":"He hōʻike, ʻaʻole he hoʻohiki","f.proof.p":"Hōʻike kēlā me kēia hāʻawi i ka mea i loli: nā waihona, ka ʻokoʻa, nā kiʻi pale. ʻAʻole pono e wehe i kēlā me kēia ʻapp e ʻike ai ua pau.","f.chat.h":"E kamaʻilio me kou mau alakaʻi","f.chat.p":"He alahaka e like me Discord: hoʻokahi hōʻailona no kēlā me kēia papahana, nā daimana poni no ka mea e makemake ana iā ʻoe. E hoʻouna i kahi manaʻo i ka alakaʻi; hoʻololi ʻo ia i mau kāleka a me ka manaʻo hana, me ke pihi ✅ Go.","f.tidy.h":"Mālama i ia iho","f.tidy.p":"Hui nā kāleka pili i hoʻokahi, hoʻoponopono ʻia nā poʻo inoa pohihihi, a mālama ka nānā token i ke code i māmā. ʻOi aku ka liʻiliʻi o nā mea e hoʻololi ai, ka liʻiliʻi o ka noʻonoʻo.","f.private.h":"Nou, ma kāu kamepiula","f.private.li1":"Holo ka papa ma kāu mīkini ponoʻī a pane iā ʻoe wale nō.","f.private.li2":"Ua hūnā ʻia nā DM pilikino ma waena o nā kānaka mai ke kiko a i ke kiko.","f.private.li3":"ʻAʻohe moʻokāki, ʻaʻohe mea alualu, ʻaʻohe kuki.","f.lang.h":"Ma kāu ʻōlelo","f.lang.p":"Ma luna o 120 ʻōlelo, mai ka Holani, ka Wales a me ka Kepani a hiki i ka ʻōlelo pailaka, ʻo Yoda a me Klingon, me ka hoʻololi wikiwiki i ka Pelekānia no nā huaʻōlelo ʻoihana.","f.service.h":"Mai kahi manaʻo a i kahi lawelawe maoli","f.service.p":"Ua kūkulu ʻoe i kekahi mea me AI e hoʻohana ʻia nei e nā kānaka? E kaha iā ia he lawelawe a kōkua ka papa iā ʻoe e mālama pono: nā hōʻoia uptime, kahi ʻaoʻao kūlana ākea, nā hanana me ka moʻolelo i kākau ʻia, nā hoʻololi e pono ai kahi E hele, nā kope pakele i nānā ʻia i kēlā me kēia lā. Aʻo ʻo Kōkua iā ʻoe i kēlā me kēia ʻanuʻu i kou hele ʻana.","msgr.h2":"AI-gile Messenger: kou pūʻulu i loko o kou ʻeke","msgr.p1":"E kamaʻilio me kou pūʻulu AI me ka wehe ʻole i ka papa. E kamaʻilio me nā alakaʻi o kāu mau papahana a me kou mau hoaaloha, a e nānā i nā ʻanuʻu hoʻāʻo o kekahi kāleka a pane aku, mai kāu kelepona mai nō.","msgr.p2":"No ka hoʻopili ʻana, e scan i ke code QR ma kāu papa. ʻO ka manawa mua kēia? Na kekahi kamaʻilio hōʻikeʻike aloha e alakaʻi iā ʻoe.","msgr.when":"ʻO Android mua, a laila he mana pūnaewele no nā kelepona a me iPhone.","msgr.who":"Ke alakaʻi o kāu papahana","msgr.b1":"Ua mākaukau ka hoʻoponopono ʻana o ke ʻano ʻeleʻele. Makemake ʻoe i nā ʻanuʻu hoʻāʻo?","msgr.b2":"ʻAe, e ʻoluʻolu!","msgr.b3":"1. E wehe i Hoʻonohonoho. 2. E koho i ʻEleʻele. Pololei anei kona ʻano?","tl.aria":"Laina manawa mai ka kamaʻilio mua a hiki i ke ala e hiki mai ana","tl.h2":"Mai ka kamaʻilio mua a i ka mea e hiki mai ana","tl.lede":"Nā lā a me nā manawa maoli, ma kou wā ponoʻī. Ma hope o kēia lā he hoʻolālā ia, ʻaʻohe lā i hoʻohiki ʻia.","tl.today":"Kēia lā","tl.planned":"hoʻolālā ʻia","tl.cards.one":"{n} kāleka","tl.cards.other":"{n} kāleka","join.h2":"E komo mai","join.lede":"Ke kūkulu ʻia nei ʻo AI-gile e kekahi kanaka ʻumiʻumi ʻano ʻē, he AuDHD kona a me kekahi mau hakakā me ke olakino noʻonoʻo, a e nā agent ahonui he nui loa. He pilikino ia i kēia manawa, ma ka alpha pani ʻia me nā hoaaloha. Makemake ʻoe e hoʻāʻo ke wehe ʻia?","join.btn":"E kākau i kou hoihoi","join.small":"E leka uila aku mākou iā ʻoe, ʻaʻohe mea ʻē aʻe","footer.tag":"AI-gile. ʻAʻohe mea alualu, ʻaʻohe kuki, ʻaʻohe kope kū hālāwai.","footer.licence":"ʻAe ʻoihana","footer.status":"Kūlana","footer.privacy":"Ka mea a mākou e mālama ai","footer.thanks":"Nā kelepona me ka mahalo iā ChilledChat","form.sending":"Ke hoʻouna nei…","form.failed":"ʻAʻole i hana kēlā: e hoʻāʻo hou ma hope.","form.offline":"ʻAʻole hiki ke hōʻea iā AI-gile: e hoʻāʻo hou ma hope.","form.keep":"Hoʻohana mākou i kēia no ka pane ʻana iā ʻoe wale nō, a laila holoi mākou. ʻAʻohe mea alualu, ʻaʻohe kuki.","form.keepLink":"Ka mea a mākou e mālama ai","interest.title":"AI-gile: e haʻi mai iaʻu ke wehe ʻia ka alpha","interest.description":"E waiho i kāu leka uila e lohe ai i ka wā e wehe ai ka alpha a i ʻole ka beta pani ʻia o AI-gile.","interest.h1":"🔔 E haʻi mai iaʻu ke wehe ʻia","interest.lede":"Ma ka pre-alpha pani ʻia ʻo AI-gile. E waiho i kāu leka uila a e kākau aku mākou hoʻokahi manawa, ke loaʻa kahi wahi nou.","interest.email":"Kāu leka uila","interest.which":"ʻO ka hoʻāʻo ʻehea?","interest.alpha":"Alpha pani ʻia: mua, ʻōhūhū, nui nā loli","interest.beta":"Beta: ʻoi aku ka paʻa, ma hope","interest.both":"ʻO kekahi paha, ka mea e hiki mua mai","interest.submit":"E hoʻokomo iaʻu i ka papa inoa","interest.thanks":"Mahalo! Aia ʻoe ma ka papa inoa.","licence.title":"AI-gile: ʻae ʻoihana","licence.description":"Hoʻohana ʻoe iā AI-gile ma kāu ʻoihana? E noi i ka ʻae ʻoihana manuahi.","licence.h1":"📜 ʻAe ʻoihana","licence.lede":"Hoʻohana ʻoe iā AI-gile ma ka hana? E haʻi mai ʻo wai ʻoe a he aha kāu e hana nei. Inā he pono kāna hana, manuahi ka ʻae.","licence.company":"Hui","licence.website":"Pūnaewele","licence.what":"Kāu hana","licence.how":"Pehea ia e kōkua ai i ka honua","licence.email":"Leka uila","licence.submit":"E noi","licence.thanks":"Mahalo! E pane aku mākou ma ka leka uila.","status.title":"Kūlana AI-gile","status.h1":"Kūlana AI-gile","status.quiet":"Mālie nō","status.intro":"Ke hana nei anei ʻo AI-gile i kēia manawa? Nānā kēia ʻaoʻao i ka pūnaewele, ke kaʻana papa, nā kelepona a me ka hoʻoiho i kēlā me kēia 5 minuke.","status.up":"Ke hana nei (pane ʻia i loko o {ms} ms)","status.slow":"ʻAʻole i pane i ka nānā hope loa, ke hoʻāʻo hou nei","status.down":"Pio: ʻaʻole i pane i nā nānā hope ʻelua","status.svc.web":"Pūnaewele","status.svc.web.offers":"Kēia pūnaewele: he aha ʻo AI-gile, a me ka palapala hoihoi","status.svc.boards":"Kaʻana papa","status.svc.boards.offers":"Nā papa ākea, nā leka ma waena o nā hoaaloha a me nā kono","status.svc.calls":"Kelepona","status.svc.calls.offers":"Leo, wikiō a me ke kaʻana pale ma AI-gile","status.svc.download":"Hoʻoiho","status.svc.download.offers":"Ka mea hoʻokomo Windows a me nā loulou kono","status.checking":"Ke nānā nei…","status.offline":"ʻAʻole hiki ke hōʻea i ka lawelawe kūlana i kēia manawa (ke hoʻāʻo hou nei)","status.updated":"ua hōʻano hou ʻia {ago}","status.justNow":"i kēia manawa wale nō","status.min":"{n} minuke i hala","status.hours":"{n} hola i hala","status.days":"{n} lā i hala","privacy.title":"AI-gile: ka mea a mākou e mālama ai","privacy.h1":"Ka mea a mākou e mālama ai","privacy.lede":"Ma ke ʻano pōkole: ka mea āu e hoʻouna mai ai wale nō, ʻaʻole no ka manawa lōʻihi.","privacy.only":"Ka mea āu e hoʻouna mai ai wale nō: ka mea āu e kākau ai ma kekahi palapala, e like me kāu leka uila. ʻAʻohe mea ʻē aʻe e pili ana iā ʻoe.","privacy.sealed":"Hoʻopaʻa ʻia i ʻole e hiki i kā mākou kikowaena ke heluhelu: ma kāu polokalamu kele ma mua o kona haʻalele ʻana (ma kekahi polokalamu kele kahiko, i ka manawa e hōʻea ai). ʻO kā mākou papa ponoʻī wale nō ke hiki ke wehe.","privacy.server":"Holoi ʻia mai ke kikowaena aku i ka hōʻea ʻana i kā mākou papa. ʻO nā mea e koe ana ma laila ma hope o 30 lā, holoi ʻia nō.","privacy.board":"Mālama mākou ma kā mākou papa a hiki i ko mākou pane ʻana iā ʻoe, a laila holoi pū mākou ma laila.","privacy.none":"ʻAʻohe mea alualu, ʻaʻohe kuki, ʻaʻohe kālailai.","privacy.local":"Noho kāu ʻōlelo a me kāu koho mālamalama a pōʻeleʻele ma kāu polokalamu kele ponoʻī. ʻAʻole loa e hoʻouna ʻia mai iā mākou.","privacy.ask":"Makemake ʻoe e holoi koke ʻia? E pane i kā mākou leka uila a e haʻi mai.","live.h2":"E nānā i kona kūkulu ʻia ʻana, ola","live.caption":"Huna ʻia kēlā me kēia kāleka: ʻike ʻoe i ke ʻano o ka hana, ʻaʻole nā ʻōlelo.","live.watching.one":"ola: {n} e nānā ana","live.watching.other":"ola: {n} e nānā ana","live.last.now":"Ua neʻe ka pā hope loa i kēia manawa","live.last.min.one":"Ua neʻe ka pā hope loa {n} minuke aku nei","live.last.min.other":"Ua neʻe ka pā hope loa {n} minuke aku nei","live.last.hour.one":"Ua neʻe ka pā hope loa {n} hola aku nei","live.last.hour.other":"Ua neʻe ka pā hope loa {n} hola aku nei","live.last.day.one":"Ua neʻe ka pā hope loa {n} lā aku nei","live.last.day.other":"Ua neʻe ka pā hope loa {n} lā aku nei","live.offline":"Ke hoʻomaha iki nei ka papa ola. E hoʻi mai koke.","live.cols":"Backlog|E hana|Ke hana nei|Ke nānā nei ka pūʻulu|No ʻoe e test|No ka pūʻulu|Pau"},"lines":{"unit":"words","sizes":[{"n":1,"texts":["Kanban.","Robot.","Hāʻawi."]},{"n":2,"texts":["Kanban robot.","Robot ʻoli.","Manaʻo, kūkulu."]},{"n":3,"texts":["Kanban no nā robot.","Lilo ka manaʻo hiʻona.","Kanban mea hana manuahi."]},{"n":5,"texts":["Papa kanban a nā mea hana.","Kākau kāleka. Kūkulu nā mea hana.","Manuahi, kūloko, hoʻāʻo ʻia, lealea iki."]},{"n":8,"texts":["Papa kanban manuahi, hana nā mea hana AI.","Kākau i manaʻo. Kūkulu nā mea hana. ʻAe ʻoe.","Agile no ke kanaka a me nā robot ʻoli."]},{"n":13,"texts":["Papa kanban ma kāu kamepiula, lawe nā mea hana AI i nā kāleka.","E kākau i kahi manaʻo. Kūkulu kekahi pūʻulu mea hana iā ia. Nānā ka mea hoʻāʻo.","Manuahi, ʻaʻohe moʻokāki a mea alualu: he papa, kekahi mau robot, a ʻo ʻoe ka luna."]},{"n":21,"texts":["He papa kanban ʻo AI-gile no ka hana pū me nā mea hana hoʻopaʻa code AI. Lawe lākou i nā kāleka; hoʻāʻo ʻoe a ʻae.","Loaʻa i ka papahana kēlā me kēia kahi alakaʻi a me pūʻulu mea hana AI. ʻŌlelo ma kekahi kāleka, hoʻomaka ka pūʻulu.","He papa hana pilikino manuahi e holo ana ma kāu kamepiula ponoʻī. He mau robot nā limahana. ʻO ʻoe ka mea e ʻōlelo ana ʻae."]},{"n":34,"texts":["Waiho ʻoe i nā manaʻo ma ka papa. Hoʻololi kekahi pūʻulu mea hana AI iā lākou i mau hiʻona hana, hoʻāʻo, a hoʻihoʻi me nā ʻanuʻu. ʻAʻohe mea i pau a ʻōlelo ʻoe.","He papa kanban hale ʻo AI-gile a Rich i kūkulu ai me ke kōkua o nā mea hana āna e alakaʻi nei. Manuahi, holo ma kāu kamepiula, kaʻana like me nā hoaaloha, ʻaʻole kūʻai.","E noʻonoʻo i kahi papa kanban maʻamau, me nā kolamu mai Backlog a Pau, akā lawe nā mea hana AI i nā kāleka. Hōʻike lākou i ka holomua, nīnau ke paʻa, a kali mau i kou ʻae ʻana."]},{"n":55,"texts":["He papa kanban ʻo AI-gile a he mau mea hana AI ka pūʻulu. He alakaʻi kā kēlā me kēia papahana nāna e hoʻolālā, a he mau kōkua nāna e kūkulu. Ke mākaukau kekahi hiʻona, hoʻāʻo ka mea hoʻāʻo AI a lawe i kiʻi pale, a hiki i kāu puʻu. E ʻae, a i ʻole e ʻōlelo a hana hou lākou.","Hoʻomaka ia ma ke ʻano he ala o hoʻokahi kanaka e mālama i nā hālāwai hoʻopaʻa code AI he nui i ka manawa hoʻokahi, a ulu ia i papa kūpono. Holo ia ma kāu mīkini, ʻaʻole noi i moʻokāki, a ʻaʻohe mea alualu. ʻAʻole naʻe i pau, no laila e manaʻo i nā ʻaoʻao ʻōhūhū a me kekahi mea e kāhāhā ai.","Eia ka mana ʻoiaʻiʻo. Pono nō ʻoe e loaʻa nā manaʻo a nānā i nā hopena. Hana ʻo AI-gile i nā mea ma waena: mālama i nā kāleka, hoʻāla i ka mea hana kūpono ke ʻōlelo ʻoe, hōʻike i ka mea i loli, a hōʻuluʻulu i hoʻokahi puʻu pōkole nou."]},{"n":89,"texts":["He papa kanban manuahi ʻo AI-gile e holo ana ma kāu kamepiula. Loaʻa i kēlā me kēia papahana kahi pūʻulu mea hana AI: he alakaʻi nāna e hoʻololi i kou mau manaʻo i kāleka a me hoʻolālā, a he mau kōkua nāna e lawe i nā kāleka. Ke kūkulu ʻia kekahi mea, hahai ka mea hoʻāʻo AI i nā ʻanuʻu a hōʻike i kāna i ʻike ai. A laila kali ia ma kahi puʻu i kapa ʻia No ʻoe. ʻAe ʻoe, a i ʻole ʻōlelo a hoʻāʻo hou ka pūʻulu. ʻAʻohe mea e hiki i Pau me ʻoe ʻole.","Aia kekahi mau hiʻona āu e manaʻo ʻole ai. Mālama ke kiaʻi pō i ke kolamu Hana i piha i kou hiamoe ʻana, me nā kāleka ʻaʻole pono i kāu pane. Hōʻike ka helu token i ka hoʻohana o kēia lā a me kēia pule, a ʻōlelo ke ʻano ʻAʻohe Hōʻailona e hoʻōki. Hiki iā ʻoe ke hoʻouna i nā leka i nā hoaaloha, hūnā ʻia mai ke kiko a i ke kiko. Kamaʻilio ka papa i kahi o 120 ʻōlelo, me ka Holani, ka pailaka a me Klingon. ʻAʻohe kumukūʻai, a ʻaʻohe mea e hoʻāʻo nei e kūʻai aku iā ʻoe.","He papahana liʻiliʻi pilikino ʻo AI-gile, ʻaʻole he hui. Makemake ʻo Rich e mālama i nā papahana hoʻopaʻa code AI he nui me ka wehe ʻole i kēlā me kēia ʻapp e nānā ai, no laila kūkulu ʻo ia a me nā mea hana i papa no ia, a laila hoʻohana i ka papa e kūkulu i ke koena. Aia ia ma ka pre-alpha pani ʻia, ʻo ia hoʻi, hana ia, ʻo ka hapa nui, no kekahi mau hoaaloha. ʻAʻohe ʻaoʻao kumukūʻai, ʻaʻohe nūhou leka, a ʻaʻohe hoʻolālā ulu. Inā ʻike ʻia he kōkua, hiki iā ʻoe ke noi e hoʻāʻo ke wehe ākea iki ʻia."]},{"n":144,"texts":["He papa kanban ʻo AI-gile no hoʻokahi kanaka a me nā mea hana AI he nui. Holo ia ma kāu kamepiula a manuahi loa. Hoʻohui ʻoe i nā papahana, a loaʻa i kēlā me kēia kahi alakaʻi a me kahi pūʻulu liʻiliʻi. Kamaʻilio ʻoe me ka alakaʻi, e like me Discord, a wehewehe i kahi manaʻo; hoʻololi ia i mau kāleka a me kahi hoʻolālā, a kali e kaomi ʻoe i Go. Hana ka pūʻulu ma nā kāleka ma ke ʻano koʻikoʻi, me kahi laina kauoha maʻalahi no nā kumu hoʻohālike ʻōlelo. Ma mua o ka hoʻi ʻana mai, hahai ka mea hoʻāʻo AI i nā ʻanuʻu ma kahi kope o ka ʻapp a hoʻohui i kiʻi pale. Hiki ka hana i pau i kāu puʻu me nā waihona i loli a me ka ʻokoʻa. ʻAe ʻoe, a i ʻole ʻōlelo ʻoe a hoʻāʻo hou ka pūʻulu. ʻO ʻoe wale nō hiki ke hoʻoneʻe i kāleka i Pau.","He lā me AI-gile, ma kahi o ia. I ke ahiahi waiho ʻoe i kekahi mau ʻōlelo: aia kēia pihi ma ka wahi hewa, pono e hoʻokaʻina ʻia kēlā papa inoa, hiki paha iā mākou ke loaʻa i ke ʻano ʻeleʻele. Hiamoe ʻoe. Heluhelu nā mea hana i nā ʻōlelo, hana i nā loli, hoʻāʻo iā lākou a hoʻihoʻi iā ʻoe. Inā hakahaka ka Hana, hoʻopiha ke kiaʻi pō iā ia mai ka backlog me nā kāleka ʻaʻole pono i kāu pane. I ke kakahiaka he hoʻokahi puʻu pōkole: ʻelua nīnau a me kekahi mau mea e hoʻāʻo ai, me nā ʻanuʻu hiki i ke kanaka hiamoe ke hahai a me kahi kiʻi pale e hana ana. Kaomi ʻoe, ʻae i ka maikaʻi a hoʻihoʻi i ke koena. Hōʻike ka helu token i ka mea i hoʻohana ʻia, a aia ke ʻano ʻAʻohe Hōʻailona no nā pule liʻiliʻi. A laila ʻai ʻoe i ka ʻaina kakahiaka, ʻaʻole hiki i nā mea hana ke kōkua.","ʻO ka mea mua, ka mea ʻaʻole ʻo AI-gile. ʻAʻole he hoʻomaka hui, ʻaʻole kūʻai ʻia, a ʻaʻohe mea e hōʻuluʻulu ana i kāu ʻikepili. He papa manuahi ia e holo ana ma kāu kamepiula, me ka moʻokāki ʻole, mea alualu ʻole a kuki ʻole. He wahi maikaʻi ia e ʻike ai i nā papahana hoʻopaʻa code AI a pau i ka manawa hoʻokahi, me kahi pūʻulu mea hana e hana ana i nā kāleka a ʻo ʻoe ka mea hoʻoholo. Hoʻohui ia i nā kāleka pili, hoʻoponopono i nā poʻo inoa pohihihi, a nānā i ka māmā o ke code. Kamaʻilio ia ma kahi o 120 ʻōlelo, mai ka Holani a i ka pailaka a me Klingon. Kūkulu ʻia e Rich a me nā mea hana ʻoli he nui. Aia ia ma ka pre-alpha pani ʻia, no laila ʻōhūhū ma kekahi mau wahi. Inā leʻaleʻa ia iā ʻoe, e noi me ke ahonui."]}],"quips":{"1":"Hoʻokahi huaʻōlelo. Wiwoʻole. Wiwoʻole loa paha.","3":"ʻEkolu huaʻōlelo. ʻOi aku ka pololei ma mua o ka hapa nui o nā ʻaoʻao huahana.","8":"ʻEwalu huaʻōlelo. Poto ma mua o ka hālāwai kū.","21":"He kiko moʻolelo nā lōʻihi, ma ke ala. ʻIo nō.","55":"Kanalimakūmālima huaʻōlelo. Pau ʻelua kāleka i kou heluhelu ʻana i kēia.","144":"ʻO ia ka mea lōʻihi. ʻAʻohe 233. Ua hele nā mea hana e hiamoe."}},"timeline":{"first-idea.name":"Ka manaʻo mua","first-idea.line":"Ka kamaʻilio mua loa, ma mua o ka loaʻa ʻana o kekahi code.","first-board.name":"Ka papa mua","first-board.line":"He papa e nānā ana i kona kūkulu ponoʻī: nā kāleka, nā kolamu, huki a kau, nā papahana.","team-roles.name":"Pūʻulu a me nā kuleana","team-roles.line":"Nā ʻano mea hana, nā kumu hoʻohālike pūʻulu, nā wahi a me ka mea nāna e hana i ka aha.","install.name":"Kau a me nā hoʻokuʻu","install.line":"He zip hiki i ke hoaaloha ke kau, hōʻano hou ponoʻī, nā kahawai a me ka hoʻi.","usage-saver.name":"Mālama hoʻohana","usage-saver.line":"E ana i ke kumukūʻai o nā holo, mālama i ke code i māmā, mālama i kou palena.","friends.name":"Nā hoaaloha a me ke kaʻana like","friends.line":"Nā DM pilikino, he relay hūnā ʻia, nā kono, nā kuleana a me nā papahana i kaʻana like ʻia.","languages.name":"Nā ʻōlelo","languages.line":"Kēlā me kēia kikokikona pale ma kahi waihona ʻōlelo, me ka Holani a me ka Flemish ma mua.","ai-tester.name":"Mea hoʻāʻo AI","ai-tester.line":"Nānā ka mea hoʻāʻo i kēlā me kēia hāʻawi ma mua a hōʻike i kāna i ʻike ai.","website.name":"Ka pūnaewele","website.line":"aigile.lol, ka teaser a me kēia laina manawa.","streaming.name":"Kamaʻilio a me ka kahe","streaming.line":"Discord, Twitch, OBS, ke ʻano kahe, GIF a me emoji.","no-ai.name":"Mana AI ʻole","no-ai.line":"He papa no ka poʻe hoʻopaʻa code me ka AI ʻole, a me nā papa lehulehu.","night-watch.name":"Kiaʻi pō","night-watch.line":"Mālama ke kiaʻi a me ka Scrum Master i nā pūʻulu ma ka hana i kou hiamoe ʻana.","p-more.name":"Nā mea ʻē aʻe a pau","p-more.line":"Nā manaʻo liʻiliʻi e kali ana i ko lākou wā.","p-android.name":"Kelepona a me Android","p-android.line":"E hōʻea i kāu papa mai kahi kelepona, a laila he ʻapp Android maoli.","p-release.name":"Alpha a ma hope aku","p-release.line":"Alpha pani ʻia, ka pūnaewele ola, a laila beta.","p-languages.name":"Nā ʻōlelo hou aʻe","p-languages.line":"Ma luna o hoʻokahi haneli ʻōlelo, a me ke ʻano hoʻokomo piha no ka poʻe aʻo.","p-engines.name":"Nā ʻenekini AI hou aʻe","p-engines.line":"E koho iā Claude, Codex a i ʻole Gemini no kēlā me kēia mea hana.","p-pro.name":"Hana loea","p-pro.line":"Nā lepili pilikia, nā puka hoʻohui, nā kāleka hanana a me nā pale.","p-self.name":"Ka mālama ʻana iā ʻoe","p-self.line":"Ke ʻano luhi, nā hoʻomanaʻo mālama iā ʻoe iho a me 4:20.","p-servers.name":"Nā kikowaena a me ka nui","p-servers.line":"Nā hoʻonohonoho kikowaena āpau, nā kuleana a me ka hoʻolālā ulu.","p-livestream.name":"Nā mea hou o ka kahe","p-livestream.line":"Ke kamaʻilio Twitch, nā emoji ponoʻī a me kahi nānā ola lehulehu."},"words":{"button":"📖 Nā huaʻōlelo ʻoihana","h":"📖 Ua wehewehe ʻia nā huaʻōlelo","intro":"Nā huaʻōlelo āu e ʻike ai ma AI-gile, ma ka ʻōlelo maʻalahi: ke kūkulu ʻana, ka hoʻololi palekana ʻana, ka mālama ʻana i ka hana no ka poʻe e hoʻohana ana, a me ka hana pū ʻana ma ke ʻano he hui me AI.","search":"E ʻimi i huaʻōlelo…","none":"ʻAʻohe huaʻōlelo e like me ia.","close":"Pani","count":{"one":"{count} huaʻōlelo","other":"{count} huaʻōlelo"},"groups":[{"id":"build","name":"🛠️ Ke kūkulu ʻana"},{"id":"change","name":"🔀 Ka hoʻololi palekana ʻana"},{"id":"run","name":"🛎️ Ka mālama ʻana i kahi lawelawe"},{"id":"team","name":"🤝 Ka hana pū ma ke ʻano he hui (a me AI)"}],"list":[{"id":"repo","g":"build","word":"Repo","text":"Ka waihona code o ka papahana a me kona moʻolelo piha o nā commits, mālama ʻia pinepine ma GitHub.","also":["repository"]},{"id":"branch","g":"build","word":"Branch","text":"He laina hana ʻokoʻa i loko o ke code, i hiki ke hana i nā hoʻololi me ka hoʻopā ʻole i ka mana nui.","also":["branches"]},{"id":"commit","g":"build","word":"Commit","text":"He kiʻi mālama ʻia o ke code, me kahi memo pōkole o ka mea i loli. Hiki iā ʻoe ke hoʻi i kekahi i nā manawa a pau.","also":["commits"]},{"id":"push","g":"build","word":"Push","text":"Ka hoʻouna ʻana i nā kiʻi mālama ʻia (commits) mai kēia kamepiula a i GitHub, i mālama ʻia a kaʻana like ʻia."},{"id":"merge","g":"build","word":"Merge","text":"Ka hoʻohui hou ʻana i nā hoʻololi o kahi lālā i ka mana nui."},{"id":"pr","g":"build","word":"Pull request","text":"Ka noi e nānā ʻia a hui ʻia nā hoʻololi o kahi lālā i ka mana nui.","also":["PR"]},{"id":"refactor","g":"build","word":"Refactor","text":"Ka hoʻomaʻemaʻe ʻana i ke code me ka hoʻololi ʻole i kāna hana: nā waihona liʻiliʻi, nā inoa akaka, emi ka hoʻopaneʻe."},{"id":"bug","g":"build","word":"Bug","text":"ʻO kahi mea i hana ʻole e like me ka mea pono.","also":["bugs"]},{"id":"test","g":"build","word":"Test","text":"Ka hoʻāʻo ʻana i kahi hana i pau e nānā inā hana ia e like me ka mea i noi ʻia, ma mua o kou ʻae ʻana.","also":["tests"],"noTip":1},{"id":"qa","g":"build","word":"QA","text":"Pōkole no quality assurance: nā hōʻoia ʻakomi e holo ana ma mua o ke ola ʻana o kekahi mea. Ke ʻulaʻula ka QA, ua hāʻule kekahi mea, a ʻaʻole hiki ke ola a hoʻoponopono ʻia.","also":["nā hōʻoia maikaʻi","quality checks"]},{"id":"deploy","g":"change","word":"Deploy","text":"Ka kau ʻana i kahi mana hou i ke ola, e laʻa ma kahi kikowaena e hoʻohana ai nā kānaka."},{"id":"release","g":"change","word":"Hoʻokuʻu","text":"He pūʻolo i kapa ʻia o ka hana i pau e ola pū ana, me nā memo pōkole o nā mea i loli. Kākau ʻo 🚀 Nā hoʻokuʻu i nā memo mai nā kāleka i pau.","also":["nā hoʻokuʻu","release","releases"]},{"id":"rollback","g":"change","word":"Rollback","text":"Ka hoʻi ʻana i ka mana hope loa i holo pono ke hoʻopilikia ka mana hou. Ma AI-gile, hana ia i papa helu o nā ʻanuʻu hoʻihoʻi i kākau ʻia ma kēlā me kēia hoʻololi.","also":["roll back","hoʻi hope"]},{"id":"live","g":"change","word":"Ola","text":"Ka mana maoli a nā kānaka e hoʻohana ai, ʻaʻole he kope no ka hoʻāʻo ʻana. Kapa pū nā mea hoʻomohala iā ia ʻo production.","also":["live","production"],"noTip":1},{"id":"change","g":"change","word":"Hoʻololi","text":"He hoʻololi i hoʻolālā ʻia i kekahi mea a nā kānaka e hilinaʻi ai, i kākau mua ʻia: he aha, no ke aha, ka pilikia, i ka manawa hea, a pehea e hoʻihoʻi ai. E hoʻomaka i hoʻokahi me 🔀 Hāpai i hoʻololi.","also":["nā hoʻololi","noi hoʻololi","change request"],"noTip":1},{"id":"risk","g":"change","word":"Pilikia","text":"He mea e hewa paha, i helu ʻia ma ka nui o ka hiki ke loaʻa a me ka ʻino. Mālama ʻo ⚠️ Nā pilikia iā lākou ma ka papa hoʻokahi, ka helu kiʻekiʻe loa ma mua, me ka lā e nānā hou ai no kēlā me kēia.","also":["nā pilikia","risk","risk register"]},{"id":"chgwin","g":"change","word":"Puka makani hoʻololi","text":"Nā manawa e ola ai nā hoʻololi, e laʻa he ahiahi Pōʻalua mālie. Ma waho o ka puka makani, ʻaʻole hiki ke hoʻopau i kahi kāleka hoʻololi, ke ʻole he pōulia.","also":["nā puka makani hoʻololi","change window"]},{"id":"gonogo","g":"change","word":"E hele / Mai hele","text":"He koho balota wikiwiki ma mua pono o ke ola ʻana o kahi hoʻololi: ʻōlelo kēlā me kēia kanaka e pono e ʻae ʻo E hele a i ʻole Mai hele. Holo wale nō ia ke ʻae like lākou.","also":["go/no go","go-no-go"]},{"id":"approval","g":"change","word":"ʻAe","text":"Ke kali ʻana i kahi ʻae ma mua o ka hoʻomaka ʻana o ka hana. Kali kahi kāleka a kekahi hoaaloha i hāpai ai, a i ʻole kahi hoʻololi, ma ✅ Nā ʻae a ʻae a hōʻole ʻoe.","also":["nā ʻae","approval"]},{"id":"quiettime","g":"change","word":"Manawa mālie","text":"He wā, e laʻa he stream, he hōʻike a i ʻole ka pō, ʻaʻohe mea e ola. Hoʻomau nā hui i ka hana a me ka hoʻāʻo, akā kali ke ola ʻana a pau ia. Ma nā wahi ʻē, kapa ʻia ʻo change freeze.","also":["nā manawa mālie","change freeze"]},{"id":"service","g":"run","word":"Lawelawe","text":"He mea āu i kūkulu ai a nā kānaka e hilinaʻi ai, e like me kahi pūnaewele a i ʻole app, i mālama ʻia i hana mau ai. E kaha i “He lawelawe kēia papahana” a e haʻi i kāna e hāʻawi ai, ʻo wai ka mea e hoʻohana ai a ʻo wai ka on-call.","also":["nā lawelawe","service"]},{"id":"uptime","g":"run","word":"Hōʻoia uptime","text":"He hōʻoia ʻakomi, i kēlā me kēia mau minuke, e pane mau ana kāu lawelawe. Inā hāʻule ia i nā manawa he nui ma ka lālani, wehe ʻo AI-gile iho i kahi kāleka hanana.","also":["uptime","nā hōʻoia uptime"]},{"id":"statuspage","g":"run","word":"ʻAoʻao kūlana","text":"He ʻaoʻao ākea e hōʻike ana inā e hana ana kahi lawelawe (ʻōmaʻomaʻo, ʻalani a i ʻole ʻulaʻula) me ka nūhou hou loa, i hiki i ka poʻe e hoʻohana ana ke nānā ma kahi o ka nīnau ʻana.","also":["nā ʻaoʻao kūlana","status page"]},{"id":"incident","g":"run","word":"Hanana","text":"He mea i haki no ka poʻe e hoʻohana ana i kēia manawa, e like me ka hāʻule ʻana o ka pūnaewele. Lele kahi kāleka 🔥 hanana i mua o ka laina: ʻo ka hoʻohana hou ʻana ka mea mua.","also":["nā hanana","pōʻino","incident"]},{"id":"major","g":"run","word":"Hanana nui","text":"He hanana nui loa: he nui nā kānaka i pā ʻia, a i ʻole aia ke kālā a i ʻole ka ʻikepili i ka pōʻino. Hoʻokahi pihi e kau ai i nā hui a pau ma luna (swarm), e hoʻāla i ka mea on-call, a e noi i kahi nūhou kūlana i kēlā me kēia 30 minuke.","also":["nā hanana nui","major incident"]},{"id":"oncall","g":"run","word":"On-call","text":"ʻO ka mea e pane ke haki kekahi mea, ʻoiai ma ka pō. He lālā hui on-call ko kēlā me kēia lawelawe i hoʻāla mua ʻia no kona mau hanana.","also":["on call"]},{"id":"replyby","g":"run","word":"Manawa pane","text":"Ka lōʻihi e kali ai kahi kāleka no ka pane mua, e laʻa hoʻokahi hola no kahi hanana. Ma hope o laila loaʻa iā ia kahi uaki ʻulaʻula, i poina ʻole ʻia kekahi mea me ka mālie. Kapa ʻia hoʻi he response target.","also":["nā manawa pane","response target"]},{"id":"postmortem","g":"run","word":"Loiloi ma hope o ka pōʻino","text":"He nānā pōkole i hope ma hope o kahi hanana: ka mea i hana ʻia, ka mea i kōkua a me ka mea e hoʻololi ai, me ka hoʻopiʻi ʻole i kekahi. ʻAʻole hiki ke pani i kahi hanana me ka ʻole o kēia.","also":["post-mortem","postmortem","post-incident review"]},{"id":"problem","g":"run","word":"Pilikia hūnā","text":"Ke kumu hūnā ma hope o hoʻokahi a ʻoi aku paha o nā hanana. Hōʻuluʻulu kahi kāleka 🧩 pilikia i nā hanana e hoʻi mau mai ana, i loaʻa a hoʻoponopono ʻia ke kumu no ka manawa pau ʻole.","also":["problem","nā pilikia hūnā"],"noTip":1},{"id":"rootcause","g":"run","word":"Kumu pono","text":"Ke kumu maoli i haki ai kekahi mea, ʻaʻole wale ka mea āu i ʻike ai e hewa ana. E hoʻoponopono i ke kumu pono a pau ka hoʻi hou ʻana mai o ka hanana.","also":["ke kumu","root cause"]},{"id":"workaround","g":"run","word":"Hana pōkole","text":"He ala e hana mau ai nā mea a mākaukau ka hoʻoponopono maoli, e like me ka hoʻomaka hou ʻana i kekahi mea ke paʻa ia. Kākau ʻia ma ka kāleka pilikia hūnā i ʻole pono kekahi e noʻonoʻo hou.","also":["workaround"]},{"id":"knownerror","g":"run","word":"Hewa i ʻike ʻia","text":"He pilikia hūnā i maopopo kona kumu a he hana pōkole kona, akā ʻaʻole i hoʻoponopono ʻia. Helu ʻo 🧩 Nā hewa i ʻike ʻia iā lākou, i hoʻohana nā kānaka a pau i ka hana pōkole ma kahi o ka ʻeli hou ʻana.","also":["nā hewa i ʻike ʻia","known error"]},{"id":"runbook","g":"run","word":"Puke hana","text":"Nā kuhikuhi ʻanuʻu ma ka ʻanuʻu no ka hoʻoponopono ʻana i kekahi ʻano pilikia i ʻike ʻia, i hana like ʻia, me ka wikiwiki, i kēlā me kēia manawa. Ma hope o kahi hanana nui, hiki i ka hui ke noi i hoʻokahi nāu e ʻae.","also":["runbook","runbooks","nā puke hana"]},{"id":"backup","g":"run","word":"Kope pakele","text":"He kope i mālama ʻia o kāu ʻikepili mai ka wā ma mua, e hilinaʻi ai inā nalo a pōʻino kekahi mea. Hana ʻo AI-gile i kope pakele o kāu mau papa i kēlā me kēia lā.","also":["nā kope pakele","backup","backups"]},{"id":"restore","g":"run","word":"Hoʻihoʻi","text":"Ka hoʻihoʻi ʻana i ka ʻikepili mai kahi kope pakele. Waiwai maoli ke kope pakele ke ʻike ʻoe hiki ke hoʻihoʻi ʻia, no laila he pono ke hoʻāʻo i kēlā me kēia manawa.","also":["ua hoʻihoʻi ʻia","restore"]},{"id":"backlog","g":"team","word":"Backlog","text":"Nā manaʻo a me nā hana i hoʻolālā ʻole ʻia. ʻAʻohe mea ma laila e hana ʻia a neʻe i Hana."},{"id":"sprint","g":"team","word":"Sprint","text":"He manawa pōkole o ka hana (ʻo ka pule a ʻelua pule paha) me kahi pūʻulu kāleka i ʻae ʻia e hoʻopau.","also":["sprints"]},{"id":"standup","g":"team","word":"Stand-up","text":"He nānā wikiwiki: ka mea i hana ai kēlā me kēia lālā, ka mea e hana ai ma hope, a me ka mea e kāohi ana iā ia.","also":["standup","stand-ups"]},{"id":"kanban","g":"team","word":"Kanban","text":"He papa me nā kolamu (Hana, Ke hana nei, Pau) kahi e neʻe ai nā kāleka mai ka hema a ka ʻākau i ka hana ʻana o ka hana."},{"id":"wip","g":"team","word":"WIP limit","text":"Hana e holo ana: ka nui loa o nā kāleka e paʻa ai kahi kolamu, i hoʻopau ka pūʻulu i nā mea ma mua o ka hoʻomaka ʻana i nā mea hou.","also":["WIP"]},{"id":"dod","g":"team","word":"Wehewehe o ka Pau","text":"Ka papa helu pōkole a ka hui o ke ʻano o “pau”, e like me ka hoʻāʻo ʻia a me ka wehewehe ʻia, ma mua o ka hāʻawi ʻia ʻana o kahi kāleka iā ʻoe. ʻO kona māhoe, ʻo ka Wehewehe o ka Mākaukau, e haʻi ana i ka wā e maopopo pono ai kahi kāleka e hoʻomaka.","also":["Definition of Done","Wehewehe o ka Mākaukau","Definition of Ready"]},{"id":"testpile","g":"team","word":"Ahu hoʻāʻo","text":"Nā kāleka i pau e kali ana nāu e hoʻāʻo, hoʻokahi ma hope o kekahi. E ʻae i hoʻokahi a i ʻole e hoʻihoʻi me kahi memo, a puka mai ka mea aʻe.","also":["test pile"]},{"id":"retro","g":"team","word":"Retro","text":"He nānā i hope i ke ʻano o ka hana a ka hui, e ʻae like ai i hoʻokahi mea e hoʻomaikaʻi ai. Ma AI-gile, noi ka retro i kahi hoʻololi i nā ʻano hana o ka hui, a ʻōlelo ʻoe ʻo Go a i ʻole ʻAʻole i kēia manawa.","also":["retros","retrospective"]},{"id":"peerreview","g":"team","word":"Loiloi hoa","text":"He mau maka ʻelua: nānā kekahi AI ʻē aʻe i ka hana o kēlā me kēia kāleka ma mua o kona hiki ʻana iā ʻoe, i emi iho nā hewa e puka.","also":["peer review","code review"]},{"id":"swarm","g":"team","word":"Swarm","text":"Nā lima a pau i ka hana: haʻalele kēlā me kēia hui i nā hana ʻē aʻe e kōkua i hoʻokahi papahana koʻikoʻi a hoʻoponopono ʻia. Kali nā papahana ʻē aʻe i kēia manawa.","also":["swarming"]},{"id":"scrummaster","g":"team","word":"Scrum Master","text":"Ka mea e mālama ana i ke kahe o ka hana: ʻike i nā kāleka paʻa, hoʻoikaika i nā hui a hoʻomanaʻo iā ʻoe i nā mea e kali ana. Ma AI-gile, hana ka Lead Scrum Master i kēia ma nā papahana a pau.","also":["Lead Scrum Master"]},{"id":"agent","g":"team","word":"Agent","text":"He AI e hana ana ma ia iho i kahi hana: heluhelu i ke code, hana i nā hoʻololi, holo i nā nānā, a hōʻike hou mai.","also":["agents"]},{"id":"token","g":"team","word":"Token","text":"Ke anakuhi e helu ʻia ai ka hoʻohana AI: ma kahi o kekahi mau huapalapala o ka kikokiko i heluhelu ʻia a kākau ʻia paha. ʻO ka emi o nā hōʻailona, ʻo ka nui aʻe ia o kāu papahana i koe.","also":["tokens"]},{"id":"hook","g":"team","word":"Hook","text":"He kauoha liʻiliʻi e holo ana ma ia iho i kahi manawa i koho ʻia, e laʻa i ka hoʻomaka ʻana o kahi kau AI, i lohe ai ka pūʻulu i kāu mau ʻōlelo.","also":["hooks"]}]}};
